// Limestone - Ray Marching, STATIC (no ubuf.u_time)
// PHILOSOPHY (v2): limestone has a nearly UNIFORM color. The dark areas are NOT
// differently-colored rock: they are SHADOWS of the irregularities. The real
// shading is already produced by the displacement normals (calcNormal on the
// perturbed map()) and the engine's ambient occlusion. Here the texture stays
// light and uniform and only ACCOMPANIES the shadow in the cavities, without
// painting fake cracks.
// Runs INSIDE shadeSurface() -> no function definitions, everything inline.
// In scope: pModel, n_model. Dock colors: u_col1 = rock, u_col2 = cavity floor.

// --- CAVITY fBm: SAME field as the displacement (scale 6.0), so the chromatic
//     darkening falls EXACTLY where the geometry is hollow -> the self-shadow
//     and the occlusion coincide with the physical depression.
vec3 cp = pModel * 6.0;

float cav  = 0.0;
float camp = 0.5;
float cnrm = 0.0;

for (int oct = 0; oct < 4; oct++) {
    vec3 ip = floor(cp);
    vec3 fr = fract(cp);
    vec3 w  = fr * fr * (3.0 - 2.0 * fr);

    float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);

    float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
    float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
    float vn = mix(z0, z1, w.z);

    cav  += camp * vn;
    cnrm += camp;
    cp   *= 2.05;   // same lacunarity as the displacement
    camp *= 0.5;
}
cav /= cnrm;   // ~[0,1]. cav < 0.5 = cavity (the displacement pushes inward).

// chromatic occlusion: only in the deeper cavities, soft.
// (the strong shading is already done by the engine light/AO: this is just a boost)
float ambientOcc = smoothstep(0.55, 0.20, cav);   // 1 at the bottom, 0 on the ridges

// --- high-frequency MICRO-GRAIN: a TONE variation, not a color one ---
vec3 gp = floor(pModel * 44.0);
float grain = fract(sin(dot(gp, vec3(12.99, 78.23, 37.71))) * 43758.5453);
grain = (grain - 0.5) * 0.06;   // +/-3%, barely noticeable

// --- COLOR: nearly uniform rock (u_col1), very slight tone variation.
float tone = 1.0 + grain;
vec3 rock = ubuf.u_col1 * tone;

// accompany the shadow in the cavities toward u_col2 (dark floor), gently:
// most of the darkening comes from light+AO; this just keeps the cavities from
// brightening too much from the ambient term alone.
rock = mix(rock, ubuf.u_col2, ambientOcc * 0.35);

textureCol = rock;

