// Limestone relief (displacement) v2 - STATIC (no t / u_time)
// THIS is what creates the real shadows: it perturbs d_surf -> the engine
// recomputes the normals (calcNormal on map()) and the AO on this field, so the
// grazing light carves real shading into the irregularities. Chromatic color is
// kept uniform. Runs INSIDE map(). In scope: d_surf, p, pModel.
// Convention: d_surf -= amp * field.

// 4 octaves of 3D value-noise: broad ridges + fine detail.
vec3 dp = pModel * 6.0;

float dnz  = 0.0;
float damp = 0.5;
float dnrm = 0.0;

for (int doct = 0; doct < 4; doct++) {
    vec3 ip = floor(dp);
    vec3 fr = fract(dp);
    vec3 w  = fr * fr * (3.0 - 2.0 * fr);

    float h000 = fract(sin(dot(ip + vec3(0.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h100 = fract(sin(dot(ip + vec3(1.0, 0.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h010 = fract(sin(dot(ip + vec3(0.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h110 = fract(sin(dot(ip + vec3(1.0, 1.0, 0.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h001 = fract(sin(dot(ip + vec3(0.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h101 = fract(sin(dot(ip + vec3(1.0, 0.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h011 = fract(sin(dot(ip + vec3(0.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);
    float h111 = fract(sin(dot(ip + vec3(1.0, 1.0, 1.0), vec3(127.1, 311.7, 74.7))) * 43758.5453);

    float z0 = mix(mix(h000, h100, w.x), mix(h010, h110, w.x), w.y);
    float z1 = mix(mix(h001, h101, w.x), mix(h011, h111, w.x), w.y);
    float vn = mix(z0, z1, w.z);

    dnz  += damp * vn;
    dnrm += damp;
    dp   *= 2.05;
    damp *= 0.5;
}
dnz /= dnrm;          // ~[0,1]. Matches the color 'cav' field (same scale).
dnz  = dnz - 0.5;     // center it: ridges outward, cavities inward

// Amplitude: higher than v1 (0.035 -> 0.055) for more incised shadows, but below
// the threshold where the ray marching "punches through" the surface. Raise with care.
d_surf -= 0.055 * dnz;
